class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        java.util.ArrayDeque<Integer> s1 = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Integer> s2 = new java.util.ArrayDeque<>();
        while (l1 != null) { s1.push(l1.val); l1 = l1.next; }
        while (l2 != null) { s2.push(l2.val); l2 = l2.next; }
        ListNode head = null;
        int carry = 0;
        while (!s1.isEmpty() || !s2.isEmpty() || carry != 0) {
            int v1 = s1.isEmpty() ? 0 : s1.pop();
            int v2 = s2.isEmpty() ? 0 : s2.pop();
            int total = v1 + v2 + carry;
            carry = total / 10;
            ListNode node = new ListNode(total % 10);
            node.next = head;
            head = node;
        }
        return head;
    }
}

var addTwoNumbers = function(l1, l2) {
    const s1 = [], s2 = [];
    while (l1 !== null) { s1.push(l1.val); l1 = l1.next; }
    while (l2 !== null) { s2.push(l2.val); l2 = l2.next; }
    let head = null;
    let carry = 0;
    while (s1.length > 0 || s2.length > 0 || carry !== 0) {
        const v1 = s1.length > 0 ? s1.pop() : 0;
        const v2 = s2.length > 0 ? s2.pop() : 0;
        const total = v1 + v2 + carry;
        carry = Math.floor(total / 10);
        const node = new ListNode(total % 10);
        node.next = head;
        head = node;
    }
    return head;
};
